/*
 * Service worker. Generated by scripts/build-content.ts from
 * scripts/sw/sw-template.js: edit the template, not public/sw.js.
 *
 * Caches:
 *   yomu-shell-<version>  the app shell plus the precache list (onboarding audio,
 *                         Tier 1 tutor clips and the first lessons, both languages)
 *   yomu-runtime-v1       hashed Next.js files, images, audio and content JSON
 *                         fetched while learning
 *   yomu-packs-v1         lesson packs the learner chose to download (managed by
 *                         the app, never deleted here)
 * API calls (/api/*) and staff pages (/staff*) always go to the network.
 */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const SHELL_CACHE = `yomu-shell-${VERSION}`;
const RUNTIME_CACHE = "yomu-runtime-v1";

async function putIfOk(cacheName, url, response) {
  if (response && response.ok) {
    const cache = await caches.open(cacheName);
    await cache.put(url, response);
  }
}

async function precacheShell() {
  const cache = await caches.open(SHELL_CACHE);
  await Promise.all(
    PRECACHE.map(async (url) => {
      try {
        const res = await fetch(url, { cache: "no-cache" });
        if (!res.ok) return;
        await cache.put(url, res.clone());
        if (url === "/") {
          // Also cache the scripts and styles the learner app shell needs.
          const html = await res.text();
          const assets = [...html.matchAll(/(?:src|href)="(\/_next\/static\/[^"]+)"/g)].map((m) => m[1]);
          const runtime = await caches.open(RUNTIME_CACHE);
          await Promise.all(
            assets.map(async (a) => {
              if (await runtime.match(a)) return;
              const r = await fetch(a);
              if (r.ok) await runtime.put(a, r);
            }),
          );
        }
      } catch {
        // Offline or flaky while installing: the next install retries.
      }
    }),
  );
}

self.addEventListener("install", (event) => {
  event.waitUntil(precacheShell().then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n.startsWith("yomu-shell-") && n !== SHELL_CACHE).map((n) => caches.delete(n)));
      await self.clients.claim();
    })(),
  );
});

async function cacheFirst(request) {
  const hit = await caches.match(request, { ignoreVary: true });
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) await putIfOk(RUNTIME_CACHE, request, res.clone());
  return res;
}

async function staleWhileRevalidate(event, request) {
  const hit = await caches.match(request, { ignoreVary: true });
  const network = fetch(request)
    .then(async (res) => {
      if (res.ok) await putIfOk(hit ? (await findCacheName(request)) || RUNTIME_CACHE : RUNTIME_CACHE, request, res.clone());
      return res;
    })
    .catch(() => undefined);
  if (hit) {
    event.waitUntil(network);
    return hit;
  }
  const res = await network;
  return res || new Response("offline", { status: 503, headers: { "Content-Type": "text/plain" } });
}

async function findCacheName(request) {
  for (const name of await caches.keys()) {
    const cache = await caches.open(name);
    if (await cache.match(request, { ignoreVary: true })) return name;
  }
  return undefined;
}

async function appShell(event) {
  const cached = await caches.match("/", { ignoreSearch: true });
  const network = fetch("/")
    .then(async (res) => {
      if (res.ok) await putIfOk(SHELL_CACHE, "/", res.clone());
      return res;
    })
    .catch(() => undefined);
  if (cached) {
    event.waitUntil(network);
    return cached;
  }
  return (await network) || new Response("Offline", { status: 503, headers: { "Content-Type": "text/plain" } });
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith("/api/") || url.pathname.startsWith("/staff")) return;

  if (request.mode === "navigate") {
    if (url.pathname === "/") event.respondWith(appShell(event));
    return;
  }
  if (/^\/(_next\/static|audio|images|icons)\//.test(url.pathname)) {
    event.respondWith(cacheFirst(request));
    return;
  }
  if (url.pathname.startsWith("/content/") || url.pathname === "/manifest.webmanifest") {
    event.respondWith(staleWhileRevalidate(event, request));
  }
});

self.addEventListener("message", (event) => {
  if (event.data === "yomu:version" && event.source) event.source.postMessage({ type: "yomu:version", version: VERSION });
});
